select policy_id, sum(hits) as hits from security_event_hits_log where __time >TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP group by policy_id
select policy_id, sum(hits) as hits from security_event_hits_log where __time >TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP and policy_id in (0)  group by policy_id
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as start_time, sum(hits) as hits from security_event_hits_log where __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') limit 10000
select policy_id,TIME_FORMAT(min(__time) ,'yyyy-MM-dd HH:mm:ss')  as first_used, TIME_FORMAT(max(__time) ,'yyyy-MM-dd HH:mm:ss') as last_used from security_event_hits_log where policy_id in (0) group by policy_id
select policy_id, sum(hits) as hits from security_event_hits_log  where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  group by policy_id order by hits desc limit 200
select policy_id, action, sum(hits) as hits from security_event_hits_log  where __time >=TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP  group by policy_id, action order by hits desc limit 200
select policy_id, sum(hits) as hits from proxy_event_hits_log where  __time >=TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP  group by policy_id
select policy_id, sum(hits) as hits from proxy_event_hits_log where  __time >=TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP and policy_id=0 group by policy_id
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as start_time, sum(hits) as hits from proxy_event_hits_log where __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') limit 10000
select policy_id,TIME_FORMAT(min(__time) ,'yyyy-MM-dd HH:mm:ss')  as first_used, TIME_FORMAT(max(__time) ,'yyyy-MM-dd HH:mm:ss') as last_used from  proxy_event_hits_log where policy_id in (0) group by policy_id
select policy_id, sum(hits) as hits from proxy_event_hits_log  where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  group by policy_id order by hits desc limit 200
select policy_id, sub_action as action, sum(hits) as hits from proxy_event_hits_log  where __time >=TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <CURRENT_TIMESTAMP  group by policy_id, sub_action order by hits desc limit 200
select sub_action as action, sum(hits) as hits from proxy_event_hits_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP  group by  sub_action
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as start_time, sub_action  as action, sum(hits) as hits from proxy_event_hits_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') , sub_action  limit 10000
SELECT sum(not_pinning_num) AS sessions, 'notPinningNum' AS type FROM traffic_metrics_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP UNION ALL SELECT sum(pinning_num) AS sessions, 'pinningNum' AS type FROM traffic_metrics_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP UNION ALL SELECT sum(maybe_pinning_num) AS sessions, 'maybePinningNum' AS type FROM traffic_metrics_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP
SELECT TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') AS statisticTime, sum(pinning_num) AS sessions FROM traffic_metrics_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP GROUP BY TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') LIMIT 10000
SELECT TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') AS statisticTime, sum(not_pinning_num) AS sessions FROM traffic_metrics_log WHERE __time>= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP GROUP BY TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') LIMIT 10000
SELECT TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') AS statisticTime, sum(maybe_pinning_num) AS sessions FROM traffic_metrics_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP GROUP BY TIME_FORMAT( MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,'PT300S'))/1000)),'YYYY-MM-dd HH:mm:ss') LIMIT 10000
select sum(total_in_bytes) as traffic_in_bytes, sum(total_out_bytes) as traffic_out_bytes  from traffic_metrics_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select sum(total_in_packets) as traffic_in_packets, sum(total_out_packets) as traffic_out_packets  from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select sum(new_conn_num) as sessions  from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'traffic_in_bytes' as type, sum(total_in_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'traffic_out_bytes' as type, sum(total_out_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss')
select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'traffic_in_packets' as type, sum(total_in_packets) as packets from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'traffic_out_packets' as type, sum(total_out_packets) as packets from traffic_metrics_log where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss')
select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'new_conn_num' as type, sum(new_conn_num) as sessions from traffic_metrics_log where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss')
select  sum(new_conn_num) as new_conn_num, sum(established_conn_num) as established_conn_num from traffic_metrics_log  where   __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'new_conn_num' as type, sum(new_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'established_conn_num' as type, sum(established_conn_num) as sessions from traffic_metrics_log where   __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  group by TIME_FORMAT(time_floor(__time,'PT30S'),'yyyy-MM-dd HH:mm:ss')
select  sum(default_in_bytes+default_out_bytes) as default_bytes, sum(allow_in_bytes+allow_out_bytes) as allow_bytes, sum(deny_in_bytes+deny_out_bytes) as deny_bytes, sum(monitor_in_bytes+monitor_out_bytes) as monitor_bytes, sum(intercept_in_bytes+intercept_out_bytes) as intercept_bytes from traffic_metrics_log  where   __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP
select  sum(default_in_packets+default_out_packets) as default_packets, sum(allow_in_packets+allow_in_packets) as allow_packets, sum(deny_in_packets+deny_out_packets) as deny_packets, sum(monitor_in_packets+monitor_out_packets) as monitor_packets, sum(intercept_in_packets+intercept_out_packets) as intercept_packets from traffic_metrics_log  where   __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select sum(default_conn_num) as default_sessions, sum(allow_conn_num) as allow_sessions, sum(deny_conn_num) as deny_sessions, sum(monitor_conn_num) as monitor_sessions, sum(intercept_conn_num) as intercept_sessions from traffic_metrics_log  where   __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'default_bytes' as type, sum(default_in_bytes+default_out_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'allow_bytes' as type,  sum(allow_in_bytes+allow_out_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'deny_bytes' as type,  sum(deny_in_bytes+deny_out_bytes) as bytes from traffic_metrics_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'monitor_bytes' as type,  sum(monitor_in_bytes+monitor_out_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'intercept_bytes' as type,  sum(intercept_in_bytes+intercept_out_bytes) as bytes from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss')
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'default_packets' as type, sum(default_in_packets+default_out_packets) as packets from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'allow_packets' as type, sum(allow_in_packets+allow_out_packets) as packets from traffic_metrics_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'deny_packets' as type, sum(deny_in_packets+deny_out_packets) as packets from traffic_metrics_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time <  CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'monitor_packets' as type, sum(monitor_in_packets+monitor_out_packets) as packets from traffic_metrics_log where  __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'intercept_packets' as type, sum(intercept_in_packets+intercept_out_packets) as packets from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss')
select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'default_conn_num' as type, sum(default_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'allow_conn_num' as type, sum(allow_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'deny_conn_num' as type, sum(deny_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'monitor_conn_num' as type, sum(monitor_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') union all select TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss') as stat_time, 'intercept_conn_num' as type, sum(intercept_conn_num) as sessions from traffic_metrics_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(time_floor(__time,'PT5M'),'yyyy-MM-dd HH:mm:ss')
select source as client_ip, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_client_ip_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP and order_by='sessions' group by source order by sessions desc limit 100
select destination as server_ip, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_server_ip_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP and order_by='sessions' group by destination order by sessions desc limit 100
select source as internal_ip, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_internal_host_log  where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP and order_by='sessions' group by source order by sessions desc limit 100
select destination as external_ip, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_external_host_log  where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP and order_by='sessions' group by destination order by sessions desc limit 100
select domain, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_website_domain_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  and order_by='bytes' group by domain order by bytes desc limit 100
select subscriber_id, sum(session_num) as sessions, sum(c2s_byte_num) as sent_bytes, sum(s2c_byte_num) as received_bytes, sum(c2s_byte_num + s2c_byte_num) as bytes,  sum(c2s_pkt_num) as sent_packets ,sum(s2c_pkt_num) as received_packets, sum(c2s_pkt_num+s2c_pkt_num) as packets from top_user_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  and order_by='sessions' group by subscriber_id order by sessions desc limit 100
select url,sum(session_num) as hits  from top_urls_log where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP  group by url order by hits desc limit 100
SELECT policy_id, APPROX_COUNT_DISTINCT_DS_HLL(isp) as num  FROM proxy_event_hits_log where  __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by policy_id
SELECT APPROX_COUNT_DISTINCT_DS_HLL(ip_object) AS uniq_client_ip, SUM(one_sided_connections) AS one_sided_connections, SUM(uncategorized_bytes) AS total_uncategorized_bytes, SUM(fragmentation_packets) AS fragmentation_packets, SUM(sequence_gap_loss) AS sequence_gap_loss_bytes, SUM(s2c_byte_num+c2s_byte_num) AS summaryTotalBytes, SUM(s2c_pkt_num+c2s_pkt_num) AS summaryTotalPackets, SUM(sessions) AS summarySessions FROM traffic_summary_log WHERE __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time < CURRENT_TIMESTAMP  LIMIT 1
(SELECT SUM(c2s_byte_num + s2c_byte_num) as total_bytes, SUM(sessions) as total_sessions, (SUM(c2s_byte_num + s2c_byte_num) * 8)/((TIMESTAMP_TO_MILLIS( CURRENT_TIMESTAMP )-TIMESTAMP_TO_MILLIS( TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) ))/1000) AS data_rate FROM traffic_protocol_stat_log WHERE __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time <  CURRENT_TIMESTAMP AND protocol_id = 'ETHERNET' LIMIT 1) UNION ALL ( SELECT SUM(sessions), 0, 0 FROM traffic_protocol_stat_log WHERE __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time <  CURRENT_TIMESTAMP AND protocol_id = 'ETHERNET' GROUP BY __time ORDER BY __time DESC LIMIT 1 )
SELECT protocol_id, SUM(sessions) as sessions,SUM(c2s_byte_num) as c2s_byte_num, SUM(c2s_pkt_num) as c2s_pkt_num, SUM(s2c_byte_num) as s2c_byte_num, SUM(s2c_pkt_num) as s2c_pkt_num FROM traffic_protocol_stat_log WHERE __time >=  TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) AND __time <  CURRENT_TIMESTAMP GROUP BY protocol_id
SELECT log_type, SUM(used_size) as used_size, SUM(max_size) * 7/10 as max_size, TIME_FORMAT(LATEST(last_storage) * 1000,'YYYY-MM-dd') as first_storage FROM ( SELECT log_type, LATEST(used_size) as used_size, LATEST(max_size) as max_size, LATEST(last_storage) as last_storage FROM sys_storage_log WHERE __time >= CURRENT_TIMESTAMP - INTERVAL '1' HOUR AND data_center != '' GROUP BY data_center,log_type ) GROUP BY log_type
select TIME_FORMAT(__time,'YYYY-MM-dd') as stat_time,log_type as type, sum(aggregate_size) as used_size from sys_storage_log where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by TIME_FORMAT(__time,'YYYY-MM-dd'), log_type
select sum(total_hit_sessions) as total_hit_sessions, sum(total_bytes_transferred) as total_bytes_transferred, sum(total_packets_transferred) as total_packets_transferred, sum(total_new_sessions) as total_new_sessions , sum(total_close_sessions) as total_close_sessions, sum(average_new_sessions_per_second) as average_new_sessions_per_second , sum(average_bytes_per_second) as average_bytes_per_second , sum(average_packets_per_second) as average_packets_per_second , COUNT(DISTINCT(device_id)) as device_num, sum(live_sessions) as average_live_sessions from ( select device_id, sum(intercept_conn_num + monitor_conn_num + deny_conn_num + allow_conn_num) as total_hit_sessions, sum(total_in_bytes + total_out_bytes) as total_bytes_transferred, sum(total_in_packets + total_out_packets) as total_packets_transferred, sum(new_conn_num) as total_new_sessions, sum(close_conn_num) as total_close_sessions, avg(nullif(new_conn_num, 0))/ 5 as average_new_sessions_per_second, avg(nullif(total_in_bytes + total_out_bytes, 0))* 8 / 5 as average_bytes_per_second, avg(nullif(total_in_packets + total_out_packets, 0))/ 5 as average_packets_per_second, avg(nullif(established_conn_num, 0)) as live_sessions from traffic_metrics_log where __time >= TIMESTAMPADD(SECOND, -3600,CURRENT_TIMESTAMP) and __time < CURRENT_TIMESTAMP group by device_id)
